package com.familyguard.parent;
import android.app.Activity;import android.os.Bundle;import android.graphics.Typeface;import android.widget.*;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import java.security.SecureRandom;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root,requests,devices;TextView status,codeView;FirebaseAuth auth;FirebaseFirestore db;ListenerRegistration requestListener,deviceListener;final Map<String,ListenerRegistration> locationListeners=new HashMap<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,40,32,24);root.setBackgroundColor(0xFFF5F7FB);TextView title=new TextView(this);title.setText("FamilyGuard Parent");title.setTextSize(27);title.setTypeface(null,Typeface.BOLD);TextView intro=new TextView(this);intro.setText("Pair a Child device and review its shared location.");Button gen=new Button(this);gen.setText("Generate pairing code");gen.setOnClickListener(v->generateCode());codeView=new TextView(this);codeView.setText("No active code");codeView.setTextSize(22);status=new TextView(this);status.setText("Connecting to Firebase...");TextView dh=new TextView(this);dh.setText("Paired devices / latest location");dh.setTextSize(20);devices=new LinearLayout(this);devices.setOrientation(1);TextView rh=new TextView(this);rh.setText("Pending permission requests");rh.setTextSize(20);requests=new LinearLayout(this);requests.setOrientation(1);root.addView(title);root.addView(intro);root.addView(gen);root.addView(codeView);root.addView(status);root.addView(dh);root.addView(devices);root.addView(rh);root.addView(requests);setContentView(root);try{FirebaseApp.initializeApp(this);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.signInAnonymously().addOnSuccessListener(x->{status.setText("Parent connected. Generate a code to pair Child.");watchRequests();watchDevices();}).addOnFailureListener(e->status.setText("Sign-in failed: "+e.getMessage()));}catch(Exception e){status.setText("Firebase setup error: "+e.getMessage());}}
 void generateCode(){if(auth.getUid()==null)return;String chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";SecureRandom r=new SecureRandom();StringBuilder s=new StringBuilder();for(int i=0;i<8;i++)s.append(chars.charAt(r.nextInt(chars.length())));String c=s.toString();Map<String,Object>d=new HashMap<>();d.put("parentUid",auth.getUid());d.put("createdAt",FieldValue.serverTimestamp());d.put("expiresAt",new Date(System.currentTimeMillis()+50L*60L*1000L));d.put("consumedBy","");db.collection("pairCodes").document(c).set(d).addOnSuccessListener(x->{codeView.setText("PAIRING CODE\\n"+c+"\\nExpires in 50 minutes");status.setText("Enter this code on the Child phone.");}).addOnFailureListener(e->status.setText("Code error: "+e.getMessage()));}
 void watchRequests(){if(requestListener!=null)requestListener.remove();requestListener=db.collection("approvalRequests").whereEqualTo("parentUid",auth.getUid()).whereEqualTo("status","pending").addSnapshotListener((snap,e)->{if(e!=null){status.setText("Sync error: "+e.getMessage());return;}requests.removeAllViews();if(snap==null||snap.isEmpty()){TextView t=new TextView(this);t.setText("No pending requests.");requests.addView(t);return;}for(DocumentSnapshot d:snap){TextView label=new TextView(this);label.setText((d.getString("childLabel")==null?"Child":d.getString("childLabel"))+" requests "+d.getString("permission"));LinearLayout row=new LinearLayout(this);Button yes=new Button(this),no=new Button(this);yes.setText("Approve");no.setText("Deny");yes.setOnClickListener(v->resolve(d.getId(),"approved"));no.setOnClickListener(v->resolve(d.getId(),"denied"));row.addView(yes,new LinearLayout.LayoutParams(0,-2,1));row.addView(no,new LinearLayout.LayoutParams(0,-2,1));requests.addView(label);requests.addView(row);}});}
 void watchDevices(){if(deviceListener!=null)deviceListener.remove();deviceListener=db.collection("familyLinks").whereEqualTo("parentUid",auth.getUid()).addSnapshotListener((snap,e)->{if(e!=null){status.setText("Device sync error: "+e.getMessage());return;}devices.removeAllViews();if(snap==null||snap.isEmpty()){TextView t=new TextView(this);t.setText("No Child device paired yet.");devices.addView(t);return;}Set<String> active=new HashSet<>();for(DocumentSnapshot d:snap){String child=d.getString("childUid");if(child==null)continue;active.add(child);TextView item=new TextView(this);String label=d.getString("childLabel")==null?"Child":d.getString("childLabel");item.setText("Device: "+label+"\\nWaiting for location…");devices.addView(item);ListenerRegistration old=locationListeners.get(child);if(old!=null)old.remove();ListenerRegistration lr=db.collection("locations").document(child).addSnapshotListener((loc,le)->{if(le!=null){item.setText("Device: "+label+"\\nLocation error: "+le.getMessage());return;}if(loc==null||!loc.exists()){item.setText("Device: "+label+"\\nWaiting for Child to start location sharing.");return;}Double lat=loc.getDouble("latitude"),lon=loc.getDouble("longitude"),acc=loc.getDouble("accuracyMeters");String a=acc==null?"":String.format(Locale.US," (±%.0f m)",acc);item.setText("Device: "+label+"\\nLatitude: "+lat+"\\nLongitude: "+lon+a+"\\nUpdated: "+loc.getTimestamp("capturedAt"));});locationListeners.put(child,lr);}for(String id:new HashSet<>(locationListeners.keySet()))if(!active.contains(id)){locationListeners.get(id).remove();locationListeners.remove(id);}});}
 void resolve(String id,String v){db.collection("approvalRequests").document(id).update("status",v,"resolvedAt",FieldValue.serverTimestamp()).addOnFailureListener(e->status.setText("Update failed: "+e.getMessage()));}
 @Override protected void onDestroy(){if(requestListener!=null)requestListener.remove();if(deviceListener!=null)deviceListener.remove();for(ListenerRegistration r:locationListeners.values())r.remove();super.onDestroy();}
}